export type LoaderSize = "inline" | "button" | "panel";

const motionQuery = "(prefers-reduced-motion: no-preference)";
const subscribeMotion = (notify: () => void) => {
  const query = matchMedia(motionQuery);
  query.addEventListener("change", notify);
  return () => query.removeEventListener("change", notify);
};

export default function Loader3D({ size = "inline", label = "Loading", decorative = false }: { size?: LoaderSize; label?: string; decorative?: boolean }) {
  const [ready, setReady] = useState(false);
  const motion = useSyncExternalStore(subscribeMotion, () => matchMedia(motionQuery).matches, () => false);
  const a11y = decorative ? { "aria-hidden": true } : { role: "status", "aria-label": label };
  return (
    <span className={`${styles.loader} ${styles[size]}`} {...a11y}>
      <span className={ready ? `${styles.fallback} ${styles.hidden}` : styles.fallback} />
      {motion && <Scene size={size} onReady={() => setReady(true)} />}
